                        const isCompany = !!inDrill;
                        const label = isCompany ? (leaf.ticker || '?') : leaf.industry;
                        const sub = isCompany ? (leaf.industry || 'Other') : `${leaf.count} COMPAN${leaf.count!==1?'IES':'Y'}`;
